  CHECK (NOT (program_type = 'specialized' AND language_code = 'ru'))
);

CREATE INDEX IF NOT EXISTS idx_wb_programs_lang ON wb_programs(language_code, program_type);

CREATE TABLE IF NOT EXISTS wb_program_levels (
