-- === Source migration: 0004_practice_examinations.sql ===
-- ============================================================================
-- Migration 0004: Practice 4 Skills + Vocabulary/Grammar, Question Bank &
-- Examinations (STRICTLY NO CERTIFICATES OF ANY KIND)
-- SAFETY: STRICTLY NON-DESTRUCTIVE. NO DROP TABLE.
-- ============================================================================

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS wb_question_bank (
  id TEXT PRIMARY KEY,
  language_code TEXT NOT NULL REFERENCES wb_languages(code),
  skill TEXT NOT NULL CHECK (skill IN ('listening', 'speaking', 'reading', 'writing', 'vocabulary', 'grammar')),
  question_type TEXT NOT NULL CHECK (question_type IN (
    'single_choice', 'multiple_choice', 'fill_blank', 'matching',
    'sentence_order', 'true_false', 'reading_comprehension',
    'listening_comprehension', 'essay', 'speaking_prompt',
    'analytical', 'situational'
  )),
  level_ref TEXT NOT NULL,
  topic TEXT NOT NULL,
  prompt_text TEXT NOT NULL,
  options_json TEXT DEFAULT '[]',
  correct_answer_json TEXT,
  rubric_json TEXT,
  explanation_vi TEXT NOT NULL,
  audio_asset_id TEXT REFERENCES wb_audio_assets(id),
  max_score REAL NOT NULL DEFAULT 1.0,
  auto_gradable INTEGER NOT NULL DEFAULT 1 CHECK (auto_gradable IN (0, 1)),
  review_status TEXT NOT NULL DEFAULT 'published',
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_wb_qbank_filter ON wb_question_bank(language_code, skill, level_ref);

CREATE TABLE IF NOT EXISTS wb_practice_exercises (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  language_code TEXT NOT NULL REFERENCES wb_languages(code),
  skill TEXT NOT NULL CHECK (skill IN ('listening', 'speaking', 'reading', 'writing', 'vocabulary', 'grammar')),
  title_vi TEXT NOT NULL,
  level_ref TEXT NOT NULL,
  topic TEXT NOT NULL,
  instructions_vi TEXT NOT NULL,
  question_ids_json TEXT NOT NULL,
  rubric_summary_vi TEXT NOT NULL,
  is_public_preview INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS wb_practice_results (
  id TEXT PRIMARY KEY,
  account_id TEXT NOT NULL REFERENCES wb_accounts(id) ON DELETE CASCADE,
  exercise_id TEXT NOT NULL REFERENCES wb_practice_exercises(id) ON DELETE CASCADE,
  language_code TEXT NOT NULL REFERENCES wb_languages(code),
  skill TEXT NOT NULL,
  answers_json TEXT NOT NULL,
  score REAL,
  max_score REAL NOT NULL,
  grading_status TEXT NOT NULL CHECK (grading_status IN ('auto_graded', 'pending_manual_review', 'partially_graded')),
  feedback_json TEXT NOT NULL DEFAULT '{}',
  submitted_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_wb_practice_results_acc ON wb_practice_results(account_id, submitted_at);

-- Examinations: strictly assessment & practice reference ONLY — NO certificate tables/columns
CREATE TABLE IF NOT EXISTS wb_examinations (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  language_code TEXT NOT NULL REFERENCES wb_languages(code),
  title_vi TEXT NOT NULL,
  framework_reference TEXT NOT NULL,
  level_ref TEXT NOT NULL,
  skills_json TEXT NOT NULL,
  topic TEXT NOT NULL,
  duration_minutes INTEGER NOT NULL,
  instructions_vi TEXT NOT NULL,
  question_ids_json TEXT NOT NULL,
  scoring_scale_json TEXT NOT NULL,
  passing_threshold REAL NOT NULL DEFAULT 60.0,
  disclaimer_vi TEXT NOT NULL DEFAULT 'WORD BRIDGE không phải đơn vị tổ chức thi chính thức và không cấp bất kỳ loại chứng chỉ nào.',
  review_status TEXT NOT NULL DEFAULT 'published',
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS wb_examination_attempts (
  id TEXT PRIMARY KEY,
  account_id TEXT NOT NULL REFERENCES wb_accounts(id) ON DELETE CASCADE,
  examination_id TEXT NOT NULL REFERENCES wb_examinations(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'in_progress' CHECK (status IN ('in_progress', 'submitted', 'graded', 'pending_manual_review')),
  draft_answers_json TEXT NOT NULL DEFAULT '{}',
  submitted_answers_json TEXT,
  score REAL,
  max_score REAL,
  score_percent REAL,
  result_breakdown_json TEXT DEFAULT '{}',
  started_at TEXT NOT NULL DEFAULT (datetime('now')),
  last_saved_at TEXT NOT NULL DEFAULT (datetime('now')),
  submitted_at TEXT
);

CREATE INDEX IF NOT EXISTS idx_wb_exam_attempts_acc ON wb_examination_attempts(account_id, started_at);


-- === Source migration: 0005_learner_meet_intelligence.sql ===
-- ============================================================================
-- Migration 0005: Learner Meet (Operational Metadata ONLY — NO chat, NO files,
-- NO recording, NO screen share) & 15 Language Intelligence Systems
-- SAFETY: STRICTLY NON-DESTRUCTIVE. NO DROP TABLE.
-- ============================================================================

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS wb_learner_meet_sessions (
  id TEXT PRIMARY KEY,
  session_code TEXT NOT NULL UNIQUE,
  room_id TEXT NOT NULL UNIQUE,
  host_account_id TEXT NOT NULL REFERENCES wb_accounts(id) ON DELETE CASCADE,
  language_code TEXT NOT NULL REFERENCES wb_languages(code),
  mode TEXT NOT NULL CHECK (mode IN ('one_to_one', 'group')),
  topic_vi TEXT NOT NULL,
  max_participants INTEGER NOT NULL CHECK (max_participants >= 2 AND max_participants <= 8),
  status TEXT NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled', 'active', 'ended', 'cancelled')),
  webrtc_provider TEXT NOT NULL DEFAULT 'unconfigured',
  recording_disabled INTEGER NOT NULL DEFAULT 1 CHECK (recording_disabled = 1),
  chat_disabled INTEGER NOT NULL DEFAULT 1 CHECK (chat_disabled = 1),
  screen_share_disabled INTEGER NOT NULL DEFAULT 1 CHECK (screen_share_disabled = 1),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  ended_at TEXT
);

CREATE TABLE IF NOT EXISTS wb_learner_meet_participants (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES wb_learner_meet_sessions(id) ON DELETE CASCADE,
  account_id TEXT NOT NULL REFERENCES wb_accounts(id) ON DELETE CASCADE,
  joined_at TEXT NOT NULL DEFAULT (datetime('now')),
  left_at TEXT,
  connection_state TEXT NOT NULL DEFAULT 'joined',
  UNIQUE(session_id, account_id, joined_at)
);

-- 15 Language Intelligence Systems Results & History
CREATE TABLE IF NOT EXISTS wb_intelligence_runs (
  id TEXT PRIMARY KEY,
  account_id TEXT NOT NULL REFERENCES wb_accounts(id) ON DELETE CASCADE,
  system_slug TEXT NOT NULL CHECK (system_slug IN (
    'language-dna', 'language-transfer-lab', 'knowledge-to-language',
    'real-world-simulator', 'language-error-genome', 'meaning-equivalence',
    'language-timeline', 'pronunciation-lab', 'knowledge-graph',
    'personal-corpus', 'context-reconstruction', 'comprehension-depth',
    'learning-recovery', 'language-quality', 'language-observatory'
  )),
  language_code TEXT NOT NULL REFERENCES wb_languages(code),
  input_json TEXT NOT NULL,
  output_json TEXT NOT NULL,
  methodology_note TEXT NOT NULL,
  confidence_level TEXT NOT NULL CHECK (confidence_level IN ('deterministic_data', 'rule_based_heuristic', 'pending_external_ai')),
  technical_limits TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'completed' CHECK (status IN ('completed', 'blocked_provider', 'failed')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  CHECK (NOT (system_slug = 'knowledge-to-language' AND language_code = 'ru'))
);

CREATE INDEX IF NOT EXISTS idx_wb_intel_account_sys ON wb_intelligence_runs(account_id, system_slug, created_at);


-- === Source migration: 0006_email_automation_jobs_audit.sql ===
-- ============================================================================
-- Migration 0006: Email Automation, Delivery Logs, Support/Contact Tickets,
-- Background Jobs, Audit Logs & Platform Configuration
-- SAFETY: STRICTLY NON-DESTRUCTIVE. NO DROP TABLE.
-- ============================================================================

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS wb_email_events (
  id TEXT PRIMARY KEY,
  idempotency_key TEXT NOT NULL UNIQUE,
  event_type TEXT NOT NULL,
  template_key TEXT NOT NULL,
  template_version TEXT NOT NULL DEFAULT '1.0.0',
  sender_address TEXT NOT NULL CHECK (sender_address IN ('noreply@wordbridge.vn', 'cskh@wordbridge.vn', 'contact@wordbridge.vn')),
  reply_to_address TEXT NOT NULL CHECK (reply_to_address IN ('cskh@wordbridge.vn', 'contact@wordbridge.vn')),
  recipient_email TEXT NOT NULL,
  account_id TEXT REFERENCES wb_accounts(id) ON DELETE SET NULL,
  subject TEXT NOT NULL,
  variables_json TEXT NOT NULL DEFAULT '{}',
  delivery_status TEXT NOT NULL DEFAULT 'QUEUED' CHECK (delivery_status IN (
    'QUEUED', 'SENT', 'ACCEPTED', 'DELIVERED', 'BOUNCED', 'FAILED', 'COMPLAINED', 'RETRYING', 'BLOCKED_UNCONFIGURED'
  )),
  provider_name TEXT NOT NULL DEFAULT 'unconfigured',
  provider_message_id TEXT,
  retry_count INTEGER NOT NULL DEFAULT 0,
  max_retries INTEGER NOT NULL DEFAULT 3,
  next_retry_at TEXT,
  last_error TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_wb_email_status ON wb_email_events(delivery_status, next_retry_at);
CREATE INDEX IF NOT EXISTS idx_wb_email_recipient ON wb_email_events(recipient_email, created_at);

CREATE TABLE IF NOT EXISTS wb_email_delivery_logs (
  id TEXT PRIMARY KEY,
  email_event_id TEXT NOT NULL REFERENCES wb_email_events(id) ON DELETE CASCADE,
  status TEXT NOT NULL,
  provider_payload_json TEXT DEFAULT '{}',
  recorded_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS wb_support_requests (
  id TEXT PRIMARY KEY,
  request_type TEXT NOT NULL CHECK (request_type IN ('support', 'contact_partnership')),
  account_id TEXT REFERENCES wb_accounts(id) ON DELETE SET NULL,
  sender_name TEXT NOT NULL,
  sender_email TEXT NOT NULL,
  subject TEXT NOT NULL,
  message_body TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'in_progress', 'resolved', 'closed')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS wb_background_jobs (
  job_name TEXT PRIMARY KEY,
  objective_vi TEXT NOT NULL,
  trigger_type TEXT NOT NULL CHECK (trigger_type IN ('cron', 'event', 'manual')),
  schedule_expr TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'paused', 'error')),
  last_run_at TEXT,
  last_result_status TEXT,
  last_error TEXT,
  consecutive_failures INTEGER NOT NULL DEFAULT 0,
  max_consecutive_failures INTEGER NOT NULL DEFAULT 5,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS wb_audit_logs (
  id TEXT PRIMARY KEY,
  actor_account_id TEXT REFERENCES wb_accounts(id) ON DELETE SET NULL,
  action TEXT NOT NULL,
  resource_type TEXT NOT NULL,
  resource_id TEXT,
  ip_address TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_wb_audit_created ON wb_audit_logs(created_at);
CREATE INDEX IF NOT EXISTS idx_wb_audit_actor ON wb_audit_logs(actor_account_id, action);

CREATE TABLE IF NOT EXISTS wb_platform_config (
  config_key TEXT PRIMARY KEY,
  config_value TEXT NOT NULL,
  description_vi TEXT NOT NULL,
  updated_by TEXT REFERENCES wb_accounts(id) ON DELETE SET NULL,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);


