INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_en_03', 'mod_en_1', 'crs_en_1', 'english-beginner-week-03', 3, 'Tuần 03: Daily life', 'Daily life', 'Làm chủ chủ đề ''Daily life'' với trọng tâm: Hiện tại đơn, thói quen, trạng từ tần suất.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 3 trong giao tiếp thực tế.', 'Hiện tại đơn, thói quen, trạng từ tần suất', '["routine", "usually", "commute", "schedule"]', '["Present Simple (khẳng định, phủ định, nghi vấn)", "Adverbs of frequency"]', 'Phát âm âm cuối -s/-es (/s/, /z/, /ɪz/)', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Daily life (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Daily life.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Daily life.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 3.', 'Tình huống giao tiếp thực tế gắn với chủ đề Daily life trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 03", "Phiếu luyện viết tuần 03"]', '["audio/en/week-03-dialogue.mp3"]', '["Bài tập từ vựng tuần 03", "Bài tập ngữ pháp tuần 03", "Bài tập nghe hiểu tuần 03"]', 'Bài kiểm tra định kỳ cuối tuần 03 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 03.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 04.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_en_04', 'mod_en_1', 'crs_en_1', 'english-beginner-week-04', 4, 'Tuần 04: Family and relationships', 'Family and relationships', 'Làm chủ chủ đề ''Family and relationships'' với trọng tâm: Sở hữu, mô tả người, quan hệ.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 4 trong giao tiếp thực tế.', 'Sở hữu, mô tả người, quan hệ', '["sibling", "colleague", "friendly", "supportive"]', '["Possessive case (''s)", "Have got / Has"]', 'Phân biệt âm /θ/ và /ð/ trong mô tả người thân', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Family and relationships (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Family and relationships.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Family and relationships.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 4.', 'Tình huống giao tiếp thực tế gắn với chủ đề Family and relationships trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 04", "Phiếu luyện viết tuần 04"]', '["audio/en/week-04-dialogue.mp3"]', '["Bài tập từ vựng tuần 04", "Bài tập ngữ pháp tuần 04", "Bài tập nghe hiểu tuần 04"]', 'Bài kiểm tra định kỳ cuối tuần 04 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 04.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 05.', 3);
