INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_en_09', 'mod_en_1', 'crs_en_1', 'english-beginner-week-09', 9, 'Tuần 09: Plans and intentions', 'Plans and intentions', 'Làm chủ chủ đề ''Plans and intentions'' với trọng tâm: Tương lai, kế hoạch.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 9 trong giao tiếp thực tế.', 'Tương lai, kế hoạch', '["intention", "arrange", "objective", "upcoming"]', '["Be going to vs. Present Continuous for future", "Will for spontaneous decisions"]', 'Dạng rút gọn tự nhiên (going to / ''ll)', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Plans and intentions (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Plans and intentions.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Plans and intentions.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 9.', 'Tình huống giao tiếp thực tế gắn với chủ đề Plans and intentions trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 09", "Phiếu luyện viết tuần 09"]', '["audio/en/week-09-dialogue.mp3"]', '["Bài tập từ vựng tuần 09", "Bài tập ngữ pháp tuần 09", "Bài tập nghe hiểu tuần 09"]', 'Bài kiểm tra định kỳ cuối tuần 09 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 09.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 10.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_en_10', 'mod_en_1', 'crs_en_1', 'english-beginner-week-10', 10, 'Tuần 10: Health and lifestyle', 'Health and lifestyle', 'Làm chủ chủ đề ''Health and lifestyle'' với trọng tâm: Từ vựng sức khỏe, lời khuyên.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 10 trong giao tiếp thực tế.', 'Từ vựng sức khỏe, lời khuyên', '["symptom", "nutrition", "exercise", "recovery"]', '["Modal verbs should / shouldn''t / must", "Expressing health conditions"]', 'Ngữ điệu đưa lời khuyên lịch sự', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Health and lifestyle (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Health and lifestyle.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Health and lifestyle.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 10.', 'Tình huống giao tiếp thực tế gắn với chủ đề Health and lifestyle trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 10", "Phiếu luyện viết tuần 10"]', '["audio/en/week-10-dialogue.mp3"]', '["Bài tập từ vựng tuần 10", "Bài tập ngữ pháp tuần 10", "Bài tập nghe hiểu tuần 10"]', 'Bài kiểm tra định kỳ cuối tuần 10 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 10.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 11.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_en_11', 'mod_en_1', 'crs_en_1', 'english-beginner-week-11', 11, 'Tuần 11: Communication and problem solving', 'Communication and problem solving', 'Làm chủ chủ đề ''Communication and problem solving'' với trọng tâm: Hội thoại tình huống, yêu cầu làm rõ.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 11 trong giao tiếp thực tế.', 'Hội thoại tình huống, yêu cầu làm rõ', '["clarify", "confirm", "solution", "feedback"]', '["Polite requests (Could you... / Would you mind...)", "Checking understanding"]', 'Ngữ điệu lên giọng ở câu hỏi xác nhận (Yes/No)', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Communication and problem solving (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Communication and problem solving.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Communication and problem solving.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 11.', 'Tình huống giao tiếp thực tế gắn với chủ đề Communication and problem solving trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 11", "Phiếu luyện viết tuần 11"]', '["audio/en/week-11-dialogue.mp3"]', '["Bài tập từ vựng tuần 11", "Bài tập ngữ pháp tuần 11", "Bài tập nghe hiểu tuần 11"]', 'Bài kiểm tra định kỳ cuối tuần 11 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 11.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 12.', 3);
